    96	        } catch (GimbalAiException failure) {
    97	            ErrorCode code = failure.kind() == GimbalAiFailureKind.TIMEOUT
    98	                    ? ErrorCode.DEPENDENCY_TIMEOUT
    99	                    : ErrorCode.DEPENDENCY_UNAVAILABLE;
