   105	        }
   106	    }
   107	
   108	    private static ErrorCode codeForFailedEvent(String downstreamCode) {
   109	        if (downstreamCode != null && downstreamCode.toUpperCase().contains("TIMEOUT")) {
   110	            return ErrorCode.DEPENDENCY_TIMEOUT;
   111	        }
   112	        return ErrorCode.DEPENDENCY_UNAVAILABLE;
   113	    }
   114	
   115	    private void writeFailed(OutputStream out, ErrorCode code) throws IOException {
   116	        Map<String, Object> data = new LinkedHashMap<>();
   117	        data.put("code", code.name());
   118	        data.put("message", DEPENDENCY_MESSAGE);
   119	        writeEvent(out, "response.failed", json(data));
   120	    }
   121	
   122	    private void writeEvent(OutputStream out, String event, String jsonData) throws IOException {
   123	        out.write(("event: " + event + "\ndata: " + jsonData + "\n\n")
   124	                .getBytes(StandardCharsets.UTF_8));
   125	        out.flush();
   126	    }
   127	
   128	    private String json(Object value) {
   129	        try {
   130	            return objectMapper.writeValueAsString(value);
   131	        } catch (Exception encoding) {
   132	            throw new IllegalStateException("failed to encode SSE event payload");
   133	        }
   134	    }
   135	}

