 11	
 12	/**
 13	 * T05 skin_assessments 单表显式 SQL（D 包写边界：受理/照片版本/输入状态列 +
 14	 * 查询投影）。绝不触碰 worker 独占列（member_id、report_*、identity_result、
 15	 * analyzing/report_ready/needs_retake/failed 转换）。
 16	 */
 17	@Repository
 18	public class AssessmentRepository {
 19	
 20	    private final JdbcTemplate jdbc;
 21	
 22	    public AssessmentRepository(JdbcTemplate jdbc) {
 23	        this.jdbc = jdbc;
 24	    }
 25	
 26	    /** 受理事务行（FOR UPDATE）：含 Java 可写列与判定所需状态列；不读取诊断列。 */
 27	    public record AcceptanceRow(UUID id, UUID gimbalId, UUID memberId, String status,
 28	                                long currentPhotoVersion, long processingRevision,
 29	                                String photoVersions) {
 30	    }
 31	
 32	    /** A03 查询投影（不含 report_payload/report_summary 大载荷；failure_detail 不再读取）。 */
 33	    public record ViewRow(UUID id, UUID gimbalId, UUID memberId, String status,
 34	                          long currentPhotoVersion, String photoVersions, UUID reportId,
 35	                          String failureCode, String identityResult) {
 36	    }
 37	
 38	    /** A05 报告行（含冻结载荷）。 */
 39	    public record ReportRow(UUID id, UUID gimbalId, UUID memberId, String status,
 40	                            String reportPayload, Instant reportReadyAt) {
 41	    }
 42	
 43	    /** A04 列表行。 */
 44	    public record ReportListRow(UUID id, UUID reportId, Instant reportReadyAt, String reportSummary) {
 45	    }
 46	
 47	    public Optional<AcceptanceRow> findByIdForUpdate(UUID id) {
 48	        var rows = jdbc.query("SELECT id, gimbal_id, member_id, status, current_photo_version,"
 49	                        + " processing_revision, photo_versions::text AS photo_versions"
 50	                        + " FROM skin_assessments WHERE id = ? FOR UPDATE",
 51	                (rs, i) -> new AcceptanceRow(
 52	                        rs.getObject("id", UUID.class),
 53	                        rs.getObject("gimbal_id", UUID.class),
 54	                        rs.getObject("member_id", UUID.class),
 55	                        rs.getString("status"),
 56	                        rs.getLong("current_photo_version"),
 57	                        rs.getLong("processing_revision"),
 58	                        rs.getString("photo_versions")),
 59	                id);
 60	        return rows.isEmpty() ? Optional.empty() : Optional.of(rows.get(0));
 61	    }
 62	
 63	    public Optional<ViewRow> findById(UUID id) {
 64	        var rows = jdbc.query("SELECT id, gimbal_id, member_id, status, current_photo_version,"
 65	                        + " photo_versions::text AS photo_versions, report_id,"
 66	                        + " failure_code, identity_result::text AS identity_result"
 67	                        + " FROM skin_assessments WHERE id = ?",
 68	                (rs, i) -> new ViewRow(
 69	                        rs.getObject("id", UUID.class),
 70	                        rs.getObject("gimbal_id", UUID.class),
 71	                        rs.getObject("member_id", UUID.class),
 72	                        rs.getString("status"),
 73	                        rs.getLong("current_photo_version"),
 74	                        rs.getString("photo_versions"),
 75	                        rs.getObject("report_id", UUID.class),
 76	                        rs.getString("failure_code"),
 77	                        rs.getString("identity_result")),
 78	                id);
 79	        return rows.isEmpty() ? Optional.empty() : Optional.of(rows.get(0));
 80	    }
 81	
 82	    public Optional<ReportRow> findByReportId(UUID reportId) {
 83	        var rows = jdbc.query("SELECT id, gimbal_id, member_id, status, report_ready_at,"
 84	                        + " report_payload::text AS report_payload"
 85	                        + " FROM skin_assessments WHERE report_id = ?",
 86	                (rs, i) -> new ReportRow(
 87	                        rs.getObject("id", UUID.class),
 88	                        rs.getObject("gimbal_id", UUID.class),
 89	                        rs.getObject("member_id", UUID.class),
 90	                        rs.getString("status"),
 91	                        rs.getString("report_payload"),
 92	                        rs.getTimestamp("report_ready_at") == null ? null
 93	                                : rs.getTimestamp("report_ready_at").toInstant()),
 94	                reportId);
 95	        return rows.isEmpty() ? Optional.empty() : Optional.of(rows.get(0));
 96	    }
 97	
 98	    public void insertQueued(UUID id, UUID gimbalId, String photoVersionsJson, UUID t13RequestId) {
 99	        // 不触碰 worker 独占列：member_id 留 NULL、identity_result 用列默认 '{}'
100	        jdbc.update("INSERT INTO skin_assessments (id, gimbal_id, status,"
101	                        + " current_photo_version, processing_revision, photo_versions,"
102	                        + " source_request_id)"
103	                        + " VALUES (?, ?, 'queued', 1, 1, ?::jsonb, ?)",
104	                id, gimbalId, photoVersionsJson, t13RequestId);
105	    }
106	
107	    /** 补拍字段级 UPDATE：Java 只写照片版本/处理代次/queued 输入状态并清失败列。 */
108	    public int updateRetake(UUID id, String photoVersionsJson, long newPhotoVersion,
109	                            long newProcessingRevision) {
110	        return jdbc.update("UPDATE skin_assessments"
111	                        + " SET photo_versions = ?::jsonb, current_photo_version = ?,"
112	                        + " processing_revision = ?, status = 'queued',"
113	                        + " failure_code = NULL, failure_detail = NULL, updated_at = now()"
114	                        + " WHERE id = ? AND status = 'needs_retake'",
115	                photoVersionsJson, newPhotoVersion, newProcessingRevision, id);
116	    }
117	
118	    /**
119	     * M3-A04 游标分页：report_ready 正式报告按 (report_ready_at, id) DESC。
120	     * fetchSize = limit + 1 用于判断 nextCursor。
121	     */
122	    public List<ReportListRow> listReports(UUID memberId, Instant cursorTime, UUID cursorId,
123	                                           int fetchSize) {
124	        if (cursorTime == null) {
125	            return jdbc.query("SELECT id, report_id, report_ready_at, report_summary::text AS report_summary"
126	                            + " FROM skin_assessments WHERE member_id = ? AND status = 'report_ready'"
127	                            + " AND report_id IS NOT NULL"
128	                            + " ORDER BY report_ready_at DESC, id DESC LIMIT ?",
129	                    (rs, i) -> mapListRow(rs), memberId, fetchSize);
130	        }
131	        return jdbc.query("SELECT id, report_id, report_ready_at, report_summary::text AS report_summary"
132	                        + " FROM skin_assessments WHERE member_id = ? AND status = 'report_ready'"
133	                        + " AND report_id IS NOT NULL"
134	                        + " AND (report_ready_at < ? OR (report_ready_at = ? AND id < ?))"
135	                        + " ORDER BY report_ready_at DESC, id DESC LIMIT ?",
136	                (rs, i) -> mapListRow(rs), memberId,
137	                Timestamp.from(cursorTime), Timestamp.from(cursorTime), cursorId, fetchSize);
138	    }
139	
140	    private static ReportListRow mapListRow(java.sql.ResultSet rs) throws java.sql.SQLException {
141	        return new ReportListRow(
142	                rs.getObject("id", UUID.class),
143	                rs.getObject("report_id", UUID.class),
144	                rs.getTimestamp("report_ready_at") == null ? null
145	                        : rs.getTimestamp("report_ready_at").toInstant(),
146	                rs.getString("report_summary"));
147	    }
148	}

