   155	     * 响应体（避免交换滞留）；预流超时 → TIMEOUT，连接失败 → UNAVAILABLE。
   156	     */
   157	    private HttpResponse<InputStream> sendForHeaders(HttpRequest request, String requestId) {
   158	        CompletableFuture<HttpResponse<InputStream>> future =
   159	                httpClient.sendAsync(request, HttpResponse.BodyHandlers.ofInputStream());
   160	        try {
   161	            return future.get(readTimeoutMillis, TimeUnit.MILLISECONDS);
   162	        } catch (TimeoutException timeout) {
   163	            cancelAndDrain(future);
   164	            log.warn("gimbal AI downstream pre-stream timeout requestId={}", requestId);
   165	            throw new GimbalAiException(GimbalAiFailureKind.TIMEOUT,
   166	                    "gimbal AI downstream timed out before streaming");
   167	        } catch (InterruptedException interrupted) {
   168	            cancelAndDrain(future);
