   170	            throw new GimbalAiException(GimbalAiFailureKind.UNAVAILABLE,
   171	                    "gimbal AI downstream call was interrupted");
   172	        } catch (ExecutionException failure) {
   173	            Throwable cause = failure.getCause();
   174	            if (cause instanceof HttpTimeoutException) {
   175	                throw new GimbalAiException(GimbalAiFailureKind.TIMEOUT,
   176	                        "gimbal AI downstream timed out before streaming");
   177	            }
   178	            log.warn("gimbal AI downstream transport failure requestId={} exception={}",
   179	                    requestId, cause == null ? "unknown" : cause.getClass().getSimpleName());
   180	            throw new GimbalAiException(GimbalAiFailureKind.UNAVAILABLE,
   181	                    "gimbal AI downstream transport failure");
   182	        }
   183	    }
