   185	    /** 取消预流 future，并在其"迟到完成"时尽力关闭响应体。 */
   186	    private static void cancelAndDrain(CompletableFuture<?> future) {
   187	        future.cancel(true);
   188	        future.whenComplete((value, error) -> {
   189	            if (value instanceof HttpResponse<?> response
   190	                    && response.body() instanceof InputStream body) {
   191	                closeQuietly(body);
   192	            }
   193	        });
