@Component
@Conditional(NonProductionCondition.class)
public class MockReportNarrationGenerator {

    /** 固定 MOCK 区域数据（联调专用；非正式算法结果）。 */
    static final String MOCK_REGION_JSON =
            "{\"regions\":{"
                    + "\"F\":{\"O\":{\"score\":40,\"label\":\"较明显\"},"
                    + "\"P\":{\"score\":62,\"label\":\"轻度\"},"
                    + "\"D\":{\"score\":81,\"label\":\"未见明显\"}},"
                    + "\"L\":{\"O\":{\"score\":35,\"label\":\"较明显\"},"
                    + "\"P\":{\"score\":28,\"label\":\"较明显\"},"
                    + "\"D\":{\"score\":55,\"label\":\"中度\"}},"
                    + "\"R\":{\"O\":{\"score\":70,\"label\":\"轻度\"},"
                    + "\"P\":{\"score\":82,\"label\":\"未见明显\"},"
                    + "\"D\":{\"score\":50,\"label\":\"中度\"}},"
                    + "\"C\":{\"O\":{\"score\":20,\"label\":\"显著\"},"
                    + "\"P\":{\"score\":50,\"label\":\"中度\"},"
                    + "\"D\":{\"score\":65,\"label\":\"轻度\"}}"
                    + "}}";

    /** 区域固定展示顺序（F→L→R→C）。 */
    private static final List<String> REGION_ORDER = List.of("F", "L", "R", "C");

    /** 区域固定展示名。 */
    private static final Map<String, String> REGION_NAMES = Map.of(
            "F", "额头",
            "L", "左脸",
            "R", "右脸",
            "C", "下巴");

    /** 播报第一句模板：四个区域名。 */
    private static final String SENTENCE_ONE_TEMPLATE = "本次完成%s、%s、%s和%s四个区域的皮肤检测。";

    /** 播报第二句模板：区域名 + 计算所得分数，交替出现。 */
    private static final String SENTENCE_TWO_TEMPLATE = "%s%s分，%s%s分，%s%s分，%s%s分。";

    private final String narrationText;
    private final List<String> deltaChunks;

    public MockReportNarrationGenerator(ObjectMapper objectMapper) {
        Map<String, Integer> scores = computeRegionScores(objectMapper);

        String fName = REGION_NAMES.get("F");
        String lName = REGION_NAMES.get("L");
        String rName = REGION_NAMES.get("R");
        String cName = REGION_NAMES.get("C");

        String sentenceOne = String.format(SENTENCE_ONE_TEMPLATE, fName, lName, rName, cName);
        String sentenceTwo = String.format(SENTENCE_TWO_TEMPLATE,
                fName, scores.get("F"),
                lName, scores.get("L"),
                rName, scores.get("R"),
                cName, scores.get("C"));

        this.deltaChunks = List.of(sentenceOne, sentenceTwo);
        this.narrationText = sentenceOne + sentenceTwo;
    }

    /** 完整播报文案（由两个 delta chunk 程序化拼接）。 */
    public String narrationText() {
        return narrationText;
    }

    /** 恰好两个 delta chunk（顺序即下发顺序）。 */
    public List<String> deltaChunks() {
        return deltaChunks;
    }

    /** 解析固定 MOCK JSON，按区域对 O/P/D 分数取算术平均并四舍五入到整数。 */
    private static Map<String, Integer> computeRegionScores(ObjectMapper objectMapper) {
        JsonNode regions;
        try {
            regions = objectMapper.readTree(MOCK_REGION_JSON).path("regions");
        } catch (Exception invalid) {
            throw new IllegalStateException("mock report narration region JSON is invalid", invalid);
        }
        Map<String, Integer> scores = new LinkedHashMap<>();
        for (String region : REGION_ORDER) {
            JsonNode regionNode = regions.path(region);
            int sum = 0;
            int count = 0;
            for (String axis : List.of("O", "P", "D")) {
                sum += regionNode.path(axis).path("score").asInt();
                count++;
            }
            scores.put(region, BigDecimal.valueOf(sum)
                    .divide(BigDecimal.valueOf(count), 0, RoundingMode.HALF_UP)
                    .intValue());
        }
        return scores;
    }
}

package cn.yuanxin.mvp.web.assessments.narration;

import cn.yuanxin.mvp.web.assessments.AssessmentReadService;
import cn.yuanxin.mvp.web.assessments.dto.AssessmentTaskView;
import cn.yuanxin.mvp.web.auth.PrincipalContext;
import cn.yuanxin.mvp.web.auth.PrincipalType;
import cn.yuanxin.mvp.web.error.ApiException;
import cn.yuanxin.mvp.web.error.ErrorCode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.http.CacheControl;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.servlet.mvc.method.annotation.StreamingResponseBody;

import java.io.IOException;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;

/**
 * MOCK 测肤报告文案播报 SSE 端点（联调增量，catalog-only）。
 *
 * <p>{@code GET /api/v1/skin-assessment-tasks/{taskId}/report-narration-stream}：
 * Bearer 认证 → 仅云台主体（APP → 403 CALLER_NOT_ALLOWED）。预流检查在请求线程按序
 * 完成——主体校验、MOCK 生成器可用性（生产 fail-closed 503）、任务可见性
 * （{@link AssessmentReadService#getTask} 内部产出 404/409）、报告就绪
 * （reportId 为空 → 404）。任一失败在返回 SSE 之前抛 {@link ApiException}，
 * 由统一异常处理映射为 JSON 错误信封与真实 HTTP 状态。</p>
 *
 * <p>预流成功后才建立 {@code text/event-stream}（{@code Cache-Control: no-store}），
 * 逐事件即时 flush，事件序列固定为 {@code start → text_delta ×2 → done}，
 * {@code seq} 从 1 起严格 +1。仅当流内出现意外 {@link RuntimeException} 时，
 * 在 {@code done} 之前写出恰好一个 {@code error} 终态（仅安全固定字段）。
 * 客户端断开（写/flush IOException）静默结束本次发送。不支持 Last-Event-ID、
 * 断点续传、重放或取消 API。</p>
 */
@RestController
@Validated
public class ReportNarrationStreamController {

    /** 流内失败终态的固定安全文案（绝不携带异常细节/堆栈）。 */
    static final String ERROR_MESSAGE = "报告播报生成失败";

    private final AssessmentReadService readService;
    private final ObjectProvider<MockReportNarrationGenerator> generatorProvider;
    private final ObjectMapper objectMapper;

    public ReportNarrationStreamController(
            AssessmentReadService readService,
            ObjectProvider<MockReportNarrationGenerator> generatorProvider,
            ObjectMapper objectMapper) {
        this.readService = readService;
        this.generatorProvider = generatorProvider;
        this.objectMapper = objectMapper;
    }

    @GetMapping(value = "/api/v1/skin-assessment-tasks/{taskId}/report-narration-stream",
            produces = MediaType.TEXT_EVENT_STREAM_VALUE)
    public ResponseEntity<StreamingResponseBody> reportNarrationStream(
            @PathVariable UUID taskId,
            PrincipalContext principal) {
        // 预流检查（请求线程，任一失败 → 统一 JSON 错误信封，绝不进入 SSE）。
        if (principal.principalType() != PrincipalType.GIMBAL) {
            throw new ApiException(ErrorCode.CALLER_NOT_ALLOWED,
                    "only a gimbal may stream the skin report narration");
        }
        MockReportNarrationGenerator generator = generatorProvider.getIfAvailable();
        if (generator == null) {
            // 生产环境 MOCK 生成器缺席：fail-closed。
            throw new ApiException(ErrorCode.DEPENDENCY_UNAVAILABLE,
                    "report narration mock is unavailable in this environment");
        }
        AssessmentTaskView view = readService.getTask(taskId, principal);
        if (view.reportId() == null) {
            // 报告未就绪：与报告投影同口径的不可见语义。
            throw new ApiException(ErrorCode.RESOURCE_NOT_VISIBLE,
                    "report not ready; narration is not available");
        }

        String requestId = principal.requestId();
        String reportId = view.reportId();
        List<String> chunks = generator.deltaChunks();
        StreamingResponseBody stream = output ->
                writeNarration(output, requestId, taskId, reportId, chunks);
        return ResponseEntity.ok()
                .contentType(MediaType.TEXT_EVENT_STREAM)
                .cacheControl(CacheControl.noStore())
                .body(stream);
    }

    /**
     * 逐事件写出并 flush。终态纪律：{@code done} 与 {@code error} 恰有其一；
     * 客户端断开或流内异常后，本方法不再写出任何后续事件。
     */
    private void writeNarration(OutputStream out, String requestId, UUID taskId,
                                String reportId, List<String> chunks) {
        int seq = 1;
        try {
            writeEvent(out, "start", json(payload(requestId, taskId, reportId, seq, null)));
            for (String chunk : chunks) {
                seq++;
                writeEvent(out, "text_delta",
                        json(payload(requestId, taskId, reportId, seq, chunk)));
            }
            seq++;
            writeEvent(out, "done", json(payload(requestId, taskId, reportId, seq, null)));
        } catch (IOException clientDisconnect) {
            // 客户端断开：静默结束本次发送（无终态、无重放/续传）。
        } catch (RuntimeException failure) {
            // 流内意外失败：尽力写出恰好一个 error 终态（仅安全固定字段）。
            try {
                writeEvent(out, "error", json(errorPayload(requestId, taskId, reportId, seq + 1)));
            } catch (Exception ignored) {
                // 客户端已断开或写入失败：无更多可做，绝不泄露异常细节。
            }
        }
    }

    /** start/text_delta/done 的 data 载荷（键序 requestId、taskId、reportId、seq[、delta]）。 */
    private static Map<String, Object> payload(String requestId, UUID taskId, String reportId,
                                               int seq, String delta) {
        Map<String, Object> data = new LinkedHashMap<>();
        data.put("requestId", requestId);
        data.put("taskId", taskId.toString());
        data.put("reportId", reportId);
        data.put("seq", seq);
        if (delta != null) {
            data.put("delta", delta);
        }
        return data;
    }

    /** error 终态的 data 载荷（键序 requestId、taskId、reportId、seq、code、message）。 */
    private static Map<String, Object> errorPayload(String requestId, UUID taskId, String reportId,
                                                    int seq) {
        Map<String, Object> data = new LinkedHashMap<>();
        data.put("requestId", requestId);
        data.put("taskId", taskId.toString());
        data.put("reportId", reportId);
        data.put("seq", seq);
        data.put("code", "INTERNAL_ERROR");
        data.put("message", ERROR_MESSAGE);
        return data;
    }

    private void writeEvent(OutputStream out, String event, String jsonData) throws IOException {
        out.write(("event: " + event + "\ndata: " + jsonData + "\n\n")
                .getBytes(StandardCharsets.UTF_8));
        out.flush();
    }

    private String json(Object value) {
        try {
            return objectMapper.writeValueAsString(value);
        } catch (Exception encoding) {
            throw new IllegalStateException("failed to encode SSE event payload");
        }
    }
}

package cn.yuanxin.mvp.web.assessments.narration;

import cn.yuanxin.mvp.web.error.ApiException;
import cn.yuanxin.mvp.web.web.EnvelopeSupport;
import cn.yuanxin.mvp.web.web.ErrorEnvelope;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.core.Ordered;
import org.springframework.core.annotation.Order;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

import java.util.Map;

/**
 * 播报流端点的<strong>预流错误</strong>渲染器（仅作用于
 * {@link ReportNarrationStreamController}）。
 *
 * <p><b>为什么需要本类</b>：{@code report-narration-stream} 以
 * {@code produces=text/event-stream} 声明且真实 SSE 客户端发送
 * {@code Accept: text/event-stream}。预流失败抛 {@link ApiException} 时，
 * 全局 {@code GlobalExceptionHandler} 返回 JSON 信封但<strong>未预设
 * Content-Type</strong>，Spring MVC 会退回到内容协商：可生产类型仅
 * {@code text/event-stream}，与请求 {@code Accept} 无法匹配 → 以
 * {@code HttpMediaTypeNotAcceptableException} 收敛为 500，丢失真实错误状态。</p>
 *
 * <p>本 advice 仅对上述控制器生效，返回与全局处理器<strong>完全相同</strong>的
 * {@link ErrorEnvelope} 信封，并<strong>显式预设</strong> {@code Content-Type:
 * application/json}（Spring MVC 对预设 Content-Type 跳过协商），从而在
 * {@code Accept: text/event-stream} 下也如实返回 403/404/409/503 等预流错误。
 * 不修改任何既有异常处理路径，不影响其它控制器。</p>
 */
@RestControllerAdvice(assignableTypes = ReportNarrationStreamController.class)
@Order(Ordered.HIGHEST_PRECEDENCE)
public class ReportNarrationStreamErrorAdvice {

    private final EnvelopeSupport envelopes;
    private final ObjectMapper objectMapper;

    public ReportNarrationStreamErrorAdvice(EnvelopeSupport envelopes, ObjectMapper objectMapper) {
        this.envelopes = envelopes;
        this.objectMapper = objectMapper;
    }

    @ExceptionHandler(ApiException.class)
    public ResponseEntity<Map<String, Object>> apiException(ApiException ex, HttpServletRequest request) {
        ErrorEnvelope body = envelopes.error(request,
                new ErrorEnvelope.ErrorBody(ex.getCode().name(), ex.getMessage(),
                        ex.isRetryable(), ex.getDetails()));
        Map<String, Object> map = objectMapper.convertValue(body, Map.class);
        HttpHeaders headers = new HttpHeaders();
        ex.getHeaders().forEach(headers::set);
        return ResponseEntity.status(ex.getHttpStatus())
                .contentType(MediaType.APPLICATION_JSON)
                .headers(headers)
                .body(map);
    }
}

