 try: tree=ET.parse(path)
 except Exception as e:errors.append(f"XML parse {path.name}: {e}");continue
 names=[]
 for diagram in tree.getroot().findall("diagram"):
  name=diagram.get("name","");names.append(name);cells=list(diagram.iter("mxCell"));ids=[c.get("id") for c in cells if c.get("id")]
  if len(ids)!=len(set(ids)):errors.append(f"duplicate cell id {path.name}:{name}")
  known=set(ids);page_cells[(path.name,name[:2])]=known
  for c in cells:
   parent=c.get("parent")
   if parent and parent not in known:errors.append(f"missing parent {path.name}:{name}:{c.get('id')}->{parent}")
   if c.get("edge")=="1":
    edge_count+=1
    for attr in ("source","target"):
     ref=c.get(attr)
     if not ref or ref not in known:errors.append(f"bad edge {path.name}:{name}:{c.get('id')} {attr}={ref}")
   if c.get("vertex")=="1":vertex_count+=1
 if len(names)!=len(set(names)):errors.append(f"duplicate page name {path.name}")
