for line in api_text.splitlines():
 m=re.match(r"^\\| ((?:M[1-5]|B0)-A\\d{2})",line)
 if m:
  api_ids.add(m.group(1));anchor_refs.extend(re.findall(r"\\b(\\d{2})/([A-Za-z0-9_-]+)\\b",line))
for page,node in anchor_refs:
 if page not in flow_pages:errors.append(f"missing flow page {page}")
 elif node not in flow_pages[page]:errors.append(f"missing flow anchor {page}/{node}")
