link_count=0
for path in md_files:
 text=path.read_text(errors="replace")
 for raw in re.findall(r"(?<!!)\\[[^\\]]*\\]\\(([^)]+)\\)",text):
  target=raw.strip()
  if " " in target and not target.startswith("<"):target=target.split(" ",1)[0]
  target=unquote(target.strip("<>"))
  if target.startswith(("http://","https://","mailto:","javascript:","data:","#","/")):continue
  link_count+=1;filepart=target.partition("#")[0];dest=(path.parent/filepart).resolve()
  if not dest.exists():errors.append(f"missing markdown link {path.relative_to(root)} -> {target}")
web=root/"web"
