 def handle_starttag(self,tag,attrs):
  d=dict(attrs)
  for k in ("href","src"):
   if k in d:self.refs.append(d[k])
static_refs=route_refs=0
valid_views={"integration","detailed","face","technical","data","tests","components","modules","usecases","flows","api","main-content"}
for path in web.rglob("*.html"):
 h=H();h.feed(path.read_text(errors="replace"))
 for ref in h.refs:
  if ref.startswith(("http://","https://","mailto:","javascript:","data:")):continue
  if ref.startswith("#"):
   route_refs+=1;parts=ref[1:].split("/")
   if parts[0] not in valid_views:errors.append(f"unknown route {ref}")
