   continue
  ppart=ref.partition("#")[0].split("?",1)[0]
  if not ppart:continue
  dest=(web/ppart.lstrip("/")) if ppart.startswith("/") else (path.parent/ppart)
  if ppart.endswith("/"):dest=dest/"index.html"
  static_refs+=1
  if not dest.exists():errors.append(f"missing static asset {path.relative_to(web)} -> {ref}")
if errors:print("\\n".join(errors));raise SystemExit(1)
print(f"PASS drawio_xml={len(drawios)} pages={len(page_cells)} vertices={vertex_count} edges={edge_count}")
